'use strict';
const LEGACY_KEY='minerva-room-v1',CLOUD_MODE_KEY='minerva-cloud-mode-v1';
let cloudGate=true; // Google sign-in is required before any chat can be viewed.
const cloudState={user:null,base:null,ready:false,busy:false,status:'本機儲存',error:'',epoch:0,loading:false,pending:null,saving:false,paused:false};
let cloudService=null,cloudInitPromise=null;
function cloudLabel(){return cloudGate&&!cloudState.ready?'登入雲端紀錄':cloudState.ready?cloudState.status:'雲端儲存'}
function showCloudError(error){cloudState.error=error?.message||'雲端操作未完成';cloudState.status='已保留本機，尚未同步';notify(cloudState.error);refreshCloudView()}
function refreshCloudView(){renderKeepDraft();if(modal.open&&document.getElementById('cloud-panel'))cloudPanel(false)}
async function ensureCloud(){if(cloudService)return cloudService;if(!cloudInitPromise){cloudInitPromise=import('./firebase-cloud.mjs').then(async module=>{cloudService=await module.connectCloud(handleCloudUser);if(cloudGate&&cloudState.user&&!cloudState.ready&&!cloudState.loading)void activateCloud().catch(showCloudError);return cloudService}).catch(error=>{cloudInitPromise=null;throw error})}return cloudInitPromise}
function handleCloudUser(user){const previous=cloudState.user?.uid;cloudState.user=user?{uid:user.uid,email:user.email||''}:null;if(previous&&previous!==user?.uid&&(cloudState.ready||cloudGate)){modal.close();cloudState.epoch++;cloudState.ready=false;cloudState.base=null;cloudState.pending=null;cloudState.paused=false;void setAgentAccess([],false);db=seed();state.active=null;state.edit=null;state.inlineCreate=null;draft=''}if(cloudGate&&user&&cloudService&&!cloudState.ready&&!cloudState.loading)void activateCloud().catch(showCloudError);refreshCloudView()}
function renderCloudGate(){return `<main class="cloud-gate"><div><h1>雲端紀錄</h1><p>${cloudState.loading?'正在載入你的紀錄…':cloudState.user?'登入完成，準備載入紀錄。':'登入 Google 帳號，開啟你的紀錄。'}</p><p class="small">此瀏覽器會保持登入；共用裝置使用完請登出。</p>${cloudState.error?`<p role="alert" class="danger">${e(cloudState.error)}</p>`:''}${btn('cloud-settings',cloudState.user?'開啟雲端儲存設定':'Google 登入','btn primary')}</div></main>`}
function cloudPanel(load=true){document.getElementById('modal-body').innerHTML=`<div id="cloud-panel"><header class="sheet-heading"><h2 id="modal-title">雲端儲存</h2>${btn('modal-cancel','完成','text-btn')}</header><p>${cloudState.user?e(cloudState.user.email):'使用 Google 帳號，跨裝置開啟自己的紀錄。'}</p><p role="status">${e(cloudState.status)}</p>${cloudState.error?`<p class="danger" role="alert">${e(cloudState.error)}</p>`:''}<div class="cloud-actions">${!cloudState.user?btn('cloud-login','Google 登入','btn primary',!cloudService||cloudState.busy?'disabled':''):`${!cloudState.ready?btn('cloud-load','使用雲端紀錄','btn primary',cloudState.busy?'disabled':''):btn('cloud-retry','立即同步','btn primary',cloudState.busy||cloudState.saving?'disabled':'')}${btn('cloud-import','匯入原本的本機紀錄','btn',cloudState.busy?'disabled':'')}${cloudState.user?`<label class="btn cloud-import-file">匯入其他網站的 JSON 備份<input id="cloud-file" type="file" accept=".json,application/json" class="sr-only" aria-label="選擇 JSON 備份" ${cloudState.busy?'disabled':''}></label>`:''}${cloudState.ready?btn('cloud-reload','重新載入雲端','btn',cloudState.busy?'disabled':''):''}${btn('cloud-logout','登出','btn',cloudState.busy?'disabled':'')}`}${btn('export','匯出目前紀錄備份','btn')}</div><p class="small">此瀏覽器會保持登入；共用裝置使用完請登出。匯入前會先下載備份。登入帳號之間的紀錄分開儲存。${cloudState.error?'如有同步衝突，請先匯出備份，再重新載入雲端。':''}</p></div>`;if(!modal.open)modal.showModal();if(load&&!cloudService){cloudState.status='正在連接 Firebase…';void ensureCloud().then(()=>{cloudState.status=cloudState.ready?cloudState.status:'已連接 Firebase';refreshCloudView()}).catch(showCloudError)}}
function adoptCloudData(data,uid,base,{dirty=false}={}){if(cloudState.user?.uid!==uid)throw Error('登入帳號已改變');validateDatabase(data);const key=LEGACY_KEY+':'+uid;const stored=localStorage.getItem(key);data=structuredClone(data);data._cloud={revision:base.revision,dirty};const serialized=JSON.stringify(data);localStorage.setItem(key,serialized);localStorage.setItem(CLOUD_MODE_KEY,'1');KEY=key;db=data;lastRaw=serialized;rawStored=serialized;lastSaved=structuredClone(data);externalChange=false;loadError=false;storageIssue='';cloudState.base=base;cloudState.ready=true;cloudGate=true;state.active=db.chats[0]?.id;state.page='chats';state.category=state.date=state.query=state.inQuery='';state.edit=null;state.inlineCreate=null;draft='';void setAgentAccess([],false);return stored}
async function activateCloud(){if(cloudState.loading)return;cloudState.loading=true;cloudState.error='';cloudState.status='正在載入雲端…';refreshCloudView();const epoch=cloudState.epoch;try{const service=await ensureCloud(),base=await service.load();if(epoch!==cloudState.epoch||base.uid!==cloudState.user?.uid)throw Error('登入帳號已改變，請重新載入');let local=null;const raw=localStorage.getItem(LEGACY_KEY+':'+base.uid);if(raw){try{local=validateDatabase(JSON.parse(raw))}catch{throw Error('此帳號的本機快取異常，請先保留瀏覽器資料再處理。')}}const dirty=local?._cloud?.dirty===true;const data=dirty?local:base.data||seed();adoptCloudData(data,base.uid,base,{dirty});cloudState.paused=dirty&&local._cloud.revision!==base.revision;cloudState.status=cloudState.paused?'同步衝突，已保留本機':dirty?'已保留本機，等待同步':'已載入雲端紀錄';if(dirty&&!cloudState.paused)queueCloudSave(db);if(cloudState.paused)cloudState.error='其他裝置已更新資料。請先匯出本機備份，再重新載入雲端。'}catch(error){if(epoch===cloudState.epoch)throw error}finally{cloudState.loading=false;if(epoch!==cloudState.epoch&&cloudGate&&cloudState.user)void activateCloud().catch(showCloudError);refreshCloudView()}}
function queueCloudSave(data){if(!cloudState.ready||!cloudState.user)return;cloudState.pending=structuredClone(data);cloudState.status='本機已儲存，等待同步';if(!cloudState.saving&&!cloudState.paused)void flushCloud().catch(showCloudError)}
async function flushCloud(){if(cloudState.saving||cloudState.paused||!cloudState.ready)return;cloudState.saving=true;const epoch=cloudState.epoch;try{while(cloudState.pending){const snapshot=cloudState.pending;cloudState.pending=null;cloudState.status='正在同步…';refreshCloudView();let base;try{base=await cloudService.save(snapshot,cloudState.base)}catch(error){if(epoch!==cloudState.epoch)return;cloudState.pending=cloudState.pending||snapshot;cloudState.paused=true;throw error}if(epoch!==cloudState.epoch)return;cloudState.base=base;const dirty=Boolean(cloudState.pending);db._cloud={revision:base.revision,dirty};const currentRaw=localStorage.getItem(KEY);if(currentRaw!==lastRaw){cloudState.paused=true;throw Error('另一分頁已更新本機資料，請重新整理。')}const serialized=JSON.stringify(db);localStorage.setItem(KEY,serialized);lastRaw=serialized;rawStored=serialized;lastSaved=structuredClone(db);cloudState.status=dirty?'本機已儲存，等待同步':'已同步至雲端';cloudState.error=''}}finally{cloudState.saving=false;if(epoch!==cloudState.epoch&&cloudState.pending)void flushCloud().catch(showCloudError);refreshCloudView()}}
async function cloudAction(action){if(cloudState.busy)return;cloudState.busy=true;cloudState.error='';refreshCloudView();try{const service=await ensureCloud();if(action==='cloud-login'){await service.login();return}if(action==='cloud-load'){await activateCloud();return}if(action==='cloud-retry'){cloudState.paused=false;queueCloudSave(db);return}if(action==='cloud-logout'){if(cloudState.saving)throw Error('正在同步，請稍後再登出');await service.logout();cloudState.ready=false;cloudState.status='已登出';return}if(action==='cloud-import'){const raw=localStorage.getItem(LEGACY_KEY);if(!raw)throw Error('此瀏覽器沒有原本的本機紀錄');const data=validateDatabase(JSON.parse(raw));const base=await service.load();if(base.data)throw Error('此帳號已有雲端紀錄。請先匯出並整理資料，避免覆蓋既有紀錄。');downloadJson(raw,'匯入前本機紀錄備份.json');modal.close();openModal('匯入本機紀錄？',`<p>將 ${data.chats.length} 個聊天與其附著思緒、假設、分類及回收桶，存至 ${e(cloudState.user.email)} 的 Firebase 空間。</p><p>原本的本機資料與剛下載的備份會保留。</p>`,()=>{void (async()=>{adoptCloudData(data,base.uid,base,{dirty:true});queueCloudSave(db)})().catch(showCloudError)});return}if(action==='cloud-reload'){downloadJson(JSON.stringify(db,null,2),'重新載入前紀錄備份.json');const base=await service.load();if(!base.data)throw Error('雲端目前沒有紀錄');adoptCloudData(base.data,base.uid,base);cloudState.pending=null;cloudState.paused=false;cloudState.error='';cloudState.status='已重新載入雲端紀錄';return}}catch(error){showCloudError(error)}finally{cloudState.busy=false;refreshCloudView()}}

document.addEventListener('change',async event=>{
 if(event.target.id!=='cloud-file')return;
 const file=event.target.files?.[0];
 if(!file||cloudState.busy||!cloudState.user)return;
 cloudState.busy=true;
 try {
   if(file.size>15_000_000)throw Error('備份檔案過大，請先分批整理後再匯入。');
   const contents=await file.text();
   const data=validateDatabase(JSON.parse(contents));
   const service=await ensureCloud();
   const base=await service.load();
   if(base.uid!==cloudState.user?.uid)throw Error('登入帳號已改變，請重新操作。');
   if(base.data)throw Error('這個帳號已有雲端紀錄。為避免覆蓋，請先整理或備份既有資料。');
   modal.close();
   openModal('匯入 JSON 備份？',
     `<p>將 ${data.chats.length} 個聊天及所屬思緒、假設與分類，匯入 ${e(cloudState.user.email)}。</p><p>原始備份檔案不會被修改。</p>`,
     ()=>{try{adoptCloudData(data,base.uid,base,{dirty:true});queueCloudSave(db)}catch(error){showCloudError(error)}});
 } catch(error){showCloudError(error)}
 finally{cloudState.busy=false}
});
